1	/**
2	 * Foam banks along the stream (refs 03–10) + whirlpool rim foam.
3	 *  - berm: ONE continuous lumpy lather bank per side, swept along the course (custom shader:
4	 *    two-scale cellular soap bubbles with derivative bump lighting, lavender crevices, pores,
5	 *    faint iridescent rim). This is what makes the banks read as continuous foam, not cotton balls.
6	 *  - puffs: instanced bubble puffs sitting ON the berm crest (silhouette lumps), in ~40-unit chunks
7	 *    so only chunks near Benny are drawn; quality 'low' halves density and uses 20-tri puffs.
8	 *  - foam rings on the whirlpool rim and along its spiral bands (rotating with the swirl)
9	 *  - flank banks (05, wave 4): one CONTINUOUS cloud bank per side that continues the berm down both
10	 *    sides of the frame to Benny's level (ref 05: banks hugging BOTH edges y≈540–1300): a lather sheet
11	 *    (berm shader, 1 draw) + world-anchored instanced puffs (1 draw), fitted to the frame edges from
12	 *    the camera each frame. Replaces wave 3's floating "flank"/"wake" raft clumps, which read as round
13	 *    islands on open water. Fixed pools, no per-frame allocation.
14	 */
15	import * as THREE from 'three';
16	import { type Course, WORLD, funnelY } from '../world/course';
17	import { EDGE_LIFT, coreLateral } from './waterRibbon';
18	import { SPIRAL_C, FUNNEL_LIFT } from './whirlpool';
19	import { FRAG_FX_GLSL, FRAG_TAIL, NOISE_GLSL, withFog } from './glsl';
20	
21	/** c = (ambient occlusion 0..1, seed 0..1, tint -1..1) → instanceColor (see PUFF_VERT) */
22	interface Puff { p: THREE.Vector3; r: number; ao: number; tint: number }
23	
24	// ---------------------------------------------------------------------------------- berm profile
25	/** berm spans e ∈ [BERM_IN, BERM_OUT] units outward from the ribbon edge (negative = over the water) */
26	export const BERM_IN = -0.6;
27	export const BERM_OUT = 1.2;
28	const hash1 = (n: number) => { const x = Math.sin(n * 127.1 + 311.7) * 43758.5453; return x - Math.floor(x); };
29	const noise1 = (x: number) => { const i = Math.floor(x), f = x - i, u = f * f * (3 - 2 * f); return hash1(i) * (1 - u) + hash1(i + 1) * u; };
30	/** 0..1 lumpiness of the bank at (s, side) — CPU only, baked into the mesh and the puff placement */
31	export function bermLump(s: number, side: number): number {
32	  return 0.55 * noise1(s * 0.33 + side * 31.7) + 0.45 * noise1(s * 1.05 + side * 7.3);
33	}
34	/** CPU cellular "bubble dome" field (0..1) so the bank silhouette is a pile of round lumps */
35	export function bermDomes(s: number, e: number, side: number): number {
36	  const gs = s / 0.95, ge = e / 0.62 + side * 11.3;
37	  const i0 = Math.floor(gs), j0 = Math.floor(ge);
38	  let best = 0;
39	  for (let di = -1; di <= 1; di++) for (let dj = -1; dj <= 1; dj++) {
40	    const i = i0 + di, j = j0 + dj;
41	    const ox = hash1(i * 17.13 + j * 3.71), oy = hash1(i * 5.31 + j * 19.7 + 4.2);
42	    const r = 0.45 + 0.4 * hash1(i * 7.7 + j * 13.1 + 9.9);
43	    const dx = (i + ox - gs) / r, dy = (j + oy - ge) / r;
44	    best = Math.max(best, 1 - (dx * dx + dy * dy));
45	  }
46	  return Math.max(0, best);
47	}
48	
49	/** height (along course up) of the bank surface at e units outward from the edge */
50	export function bermHeight(e: number, hw: number, lump: number): number {
51	  const uIn = Math.max(0, (hw + BERM_IN) / hw);
52	  const hIn = EDGE_LIFT * uIn * uIn * uIn - 0.07;
53	  const ep = 0.08 + 0.22 * lump;
54	  const hp = EDGE_LIFT + 0.14 + 0.5 * lump;
55	  const hOut = -0.95;
56	  if (e <= ep) {
57	    const t = Math.min(1, Math.max(0, (e - BERM_IN) / (ep - BERM_IN)));
58	    return hIn + (hp - hIn) * (1 - (1 - t) * (1 - t));
59	  }
60	  const t = Math.min(1, (e - ep) / (BERM_OUT - ep));
61	  return hp + (hOut - hp) * t * t;
62	}
63	
64	/** full bank surface height incl. bubble domes (shared by the mesh and the puff placement) */
65	export function bermSurface(s: number, e: number, side: number, hw: number): number {
66	  const domeK = Math.min(1, Math.max(0, (e + 0.3) / 0.35)) * Math.min(1, Math.max(0, (BERM_OUT - 0.1 - e) / 0.4));
67	  return bermHeight(e, hw, bermLump(s, side)) + 0.2 * domeK * Math.sqrt(bermDomes(s, e, side));
68	}
69	
70	const BERM_VERT = /* glsl */ `
71	attribute vec3 aFoam;    // x = e (units outward from the stream edge), y = s, z = side (-1 / 1)
72	uniform float uTime;
73	varying vec3 vFoam;
74	varying vec3 vPosW;
75	varying vec3 vNormalW;
76	#include <fog_pars_vertex>
77	void main() {
78	  // gentle breathing of the lather (never at the water line)
79	  float k = smoothstep(-0.2, 0.3, aFoam.x);
80	  vec3 p = position + normal * (0.03 * k * sin(uTime * 1.6 + aFoam.y * 2.1 + aFoam.z * 3.0));
81	  vec4 wp = modelMatrix * vec4(p, 1.0);
82	  vPosW = wp.xyz;
83	  vNormalW = normalize(mat3(modelMatrix) * normal);
84	  vFoam = aFoam;
85	  vec4 mvPosition = viewMatrix * wp;
86	  gl_Position = projectionMatrix * mvPosition;
87	  #include <fog_vertex>
88	}
89	`;
90	
91	const BERM_FRAG = /* glsl */ `
92	uniform float uTime;
93	uniform vec2 uOutro;     // amount, chamber start s
94	uniform vec3 uLightDir;
95	varying vec3 vFoam;
96	varying vec3 vPosW;
97	varying vec3 vNormalW;
98	#include <fog_pars_fragment>
99	${NOISE_GLSL}
100	${FRAG_FX_GLSL}
101	void main() {
102	  float s = vFoam.y;
103	  if (uOutro.x > 0.0 && s > uOutro.y - 2.0) {
104	    float n = vnoise(vec2(vFoam.x * 3.0, s * 0.35)) * 0.7 + 0.3;
105	    if (n < uOutro.x * 1.15) discard;
106	  }
107	  vec2 p = vec2(vFoam.x * vFoam.z * 1.1, s - uTime * 0.25);
108	  // detail fade with distance (cells per pixel)
109	  float fw = max(fwidth(p.x), fwidth(p.y));
110	  float k1 = 1.0 - smoothstep(0.12, 0.3, fw * 1.6);
111	  float k2 = 1.0 - smoothstep(0.12, 0.3, fw * 3.8);
112	  float c1 = mix(0.45, cells(p * 1.6), k1);
113	  #ifdef LOW_Q
114	  float c2 = c1;
115	  #else
116	  float c2 = mix(0.45, cells(p * 3.8 + 11.0), k2);
117	  #endif
118	  // bubble domes: bright cell centres, deep crevices between bubbles
119	  float bub = (1.0 - c1 * c1) * 0.6 + (1.0 - c2 * c2) * 0.4;
120	  vec3 N0 = normalize(vNormalW);
121	  if (!gl_FrontFacing) N0 = -N0;
122	  #ifdef LOW_Q
123	  vec3 N = N0;
124	  #else
125	  vec3 N = bumpNormal(vPosW, N0, bub * 0.1);
126	  #endif
127	  vec3 L = normalize(uLightDir);
128	  vec3 V = normalize(cameraPosition - vPosW);
129	  float diff = 0.55 + 0.45 * max(dot(N, L), 0.0);
130	  vec3 white = vec3(1.0, 1.0, 1.0);
131	  vec3 lav = vec3(0.7, 0.68, 0.98);
132	  vec3 col = mix(lav, white, 0.3 + 0.7 * clamp(N.y * 0.5 + 0.5, 0.0, 1.0)) * diff;
133	  col = mix(col, lav * 0.8, smoothstep(0.6, 0.95, c1) * 0.7 * k1);
134	  col = mix(col, lav * 0.9, smoothstep(0.65, 0.95, c2) * 0.4 * k2);
135	  // tiny pores (open bubbles)
136	  #ifndef LOW_Q
137	  vec2 pp = p * 7.0 + 5.0;
138	  float pc = cells(pp);
139	  float kp = 1.0 - smoothstep(0.1, 0.25, fw * 7.0);
140	  col = mix(col, vec3(0.58, 0.56, 0.88), (1.0 - smoothstep(0.1, 0.2, pc)) * step(0.62, hash12(floor(pp))) * 0.75 * kp);
141	  #endif
142	  float spec = pow(max(dot(reflect(-V, N), L), 0.0), 28.0);
143	  float fres = pow(1.0 - clamp(dot(N, V), 0.0, 1.0), 3.0);
144	  col += vec3(1.0) * spec * 0.45 + iridescent(fres * 1.4 + c1 * 0.6) * fres * 0.18;
145	  gl_FragColor = vec4(col * 0.96, 1.0);
146	  ${FRAG_TAIL}
147	}
148	`;
149	
150	// ---------------------------------------------------------------------------------- puffs
151	/**
152	 * Soap-foam puff (ref 05 "cloud banks": white-lavender clumps, #FCF6FF lit tops, soft lavender
153	 * undersides and crevices, a few darker pores, faint soap-film rim). instanceColor carries
154	 * (x = ambient occlusion 0..1, y = seed, z = tint -1..1), not a colour.
155	 */
156	const PUFF_VERT = /* glsl */ `
157	uniform float uTime;
158	varying vec3 vNormalW;
159	varying vec3 vPosW;
160	varying vec3 vLocal;
161	varying vec3 vInst;
162	#include <fog_pars_vertex>
163	void main() {
164	  vInst = instanceColor;
165	  float br = 1.0 + 0.035 * sin(uTime * 1.7 + instanceColor.y * 40.0);
166	  vec4 wp = modelMatrix * instanceMatrix * vec4(position * br, 1.0);
167	  vPosW = wp.xyz;
168	  vNormalW = normalize(mat3(modelMatrix) * mat3(instanceMatrix) * normal);
169	  vLocal = normal;
170	  vec4 mvPosition = viewMatrix * wp;
171	  gl_Position = projectionMatrix * mvPosition;
172	  #include <fog_vertex>
173	}
174	`;
175	const PUFF_FRAG = /* glsl */ `
176	uniform vec3 uLightDir;
177	varying vec3 vNormalW;
178	varying vec3 vPosW;
179	varying vec3 vLocal;
180	varying vec3 vInst;
181	#include <fog_pars_fragment>
182	${NOISE_GLSL}
183	void main() {
184	  vec3 N = normalize(vNormalW);
185	  vec3 V = normalize(cameraPosition - vPosW);
186	  vec3 L = normalize(uLightDir);
187	  float wrap = clamp(dot(N, L) * 0.55 + 0.5, 0.0, 1.0);
188	  float upF = clamp(N.y * 0.5 + 0.5, 0.0, 1.0);
189	  float lit = smoothstep(0.18, 0.88, wrap * 0.65 + upF * 0.35);
190	  vec3 lav = vec3(0.47, 0.44, 0.88);
191	  vec3 top = mix(vec3(1.1, 1.04, 1.16), vec3(1.04, 1.06, 1.16), clamp(vInst.z, 0.0, 1.0));
192	  top = mix(top, vec3(1.12, 1.02, 1.12), clamp(-vInst.z, 0.0, 1.0));
193	  vec3 col = mix(lav, top, lit);
194	  #ifndef LOW_Q
195	  // pores: small open bubbles on the puff skin (puff-local, two planar projections, no seam)
196	  vec3 an = abs(vLocal);
197	  vec2 pc = (an.x > an.z ? vLocal.zy : vLocal.xy) * 2.6 + vInst.y * 17.0;
198	  float cp = cells(pc);
199	  float kp = 1.0 - smoothstep(0.2, 0.45, fwidth(pc.x) + fwidth(pc.y));
200	  float pore = (1.0 - smoothstep(0.1, 0.2, cp)) * step(0.6, hash12(floor(pc) + vInst.y * 31.0));
201	  col = mix(col, lav * 0.95, pore * kp * 0.6 * lit);
202	  #endif
203	  // soap-film rim (cool lavender, a touch of pink) + soft glint
204	  float fres = pow(1.0 - clamp(dot(N, V), 0.0, 1.0), 2.4);
205	  col = mix(col, vec3(0.8, 0.68, 1.0), fres * 0.42);
206	  float spec = pow(max(dot(reflect(-V, N), L), 0.0), 26.0);
207	  col += vec3(1.0) * spec * 0.3;
208	  col *= mix(0.68, 1.0, vInst.x);
209	  gl_FragColor = vec4(col, 1.0);
210	  ${FRAG_TAIL}
211	}
212	`;
213	
214	function rng(seed: number) {
215	  let a = seed >>> 0;
216	  return () => {
217	    a = (a + 0x6d2b79f5) >>> 0;
218	    let t = a;
219	    t = Math.imul(t ^ (t >>> 15), t | 1);
220	    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
221	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
222	  };
223	}
224	
225	function makePuffMaterial(quality: 'high' | 'low') {
226	  const uniforms = withFog({
227	    uTime: { value: 0 },
228	    uLightDir: { value: new THREE.Vector3(0.3, 1.0, 0.45).normalize() },
229	  });
230	  const mat = new THREE.ShaderMaterial({
231	    uniforms,
232	    vertexShader: PUFF_VERT,
233	    fragmentShader: PUFF_FRAG,
234	    fog: true,
235	    defines: quality === 'low' ? { LOW_Q: 1 } : {},
236	  });
237	  return { mat, uniforms };
238	}
