240	/**
241	 * 05 flank-bank bubble: a camera-facing sphere IMPOSTOR (2 triangles) shaded like the soap puffs
242	 * (white-lavender lit top, lavender underside, soap-film rim that reads as the crevice between piled
243	 * bubbles, a few pores, a glint). instanceColor = (ambient occlusion, seed, tint) as for the puffs.
244	 * The quad is pushed to the sphere's front so the lather apron and neighbours cut it like a sphere.
245	 */
246	const BANK_BUB_VERT = /* glsl */ `
247	varying vec2 vP;
248	varying vec3 vInst;
249	#include <fog_pars_vertex>
250	void main() {
251	  vec4 c = modelMatrix * instanceMatrix * vec4(0.0, 0.0, 0.0, 1.0);
252	  float r = length((instanceMatrix * vec4(1.0, 0.0, 0.0, 0.0)).xyz);
253	  vec4 mvPosition = viewMatrix * c;
254	  mvPosition.xyz += normalize(-mvPosition.xyz) * r * 0.6;
255	  mvPosition.xy += position.xy * r;
256	  vP = position.xy;
257	  vInst = instanceColor;
258	  gl_Position = projectionMatrix * mvPosition;
259	  #include <fog_vertex>
260	}
261	`;
262	const BANK_BUB_FRAG = /* glsl */ `
263	uniform vec3 uLightDir;
264	uniform float uTime;
265	varying vec2 vP;
266	varying vec3 vInst;
267	#include <fog_pars_fragment>
268	${NOISE_GLSL}
269	void main() {
270	  float d2 = dot(vP, vP);
271	  if (d2 > 1.0) discard;
272	  float z = sqrt(1.0 - d2);
273	  vec3 Nv = vec3(vP, z);
274	  vec3 N = normalize((vec4(Nv, 0.0) * viewMatrix).xyz);   // view → world (rotation transpose)
275	  vec3 L = normalize(uLightDir);
276	  float wrap = clamp(dot(N, L) * 0.55 + 0.5, 0.0, 1.0);
277	  float upF = clamp(N.y * 0.5 + 0.5, 0.0, 1.0);
278	  float lit = smoothstep(0.15, 0.85, wrap * 0.6 + upF * 0.4);
279	  vec3 lav = vec3(0.5, 0.47, 0.9);
280	  vec3 top = mix(vec3(1.1, 1.05, 1.16), vec3(1.04, 1.07, 1.16), clamp(vInst.z, 0.0, 1.0));
281	  top = mix(top, vec3(1.12, 1.03, 1.13), clamp(-vInst.z, 0.0, 1.0));
282	  vec3 col = mix(lav, top, lit);
283	  // pores: one or two small open bubbles on the larger puffs
284	  vec2 pc = vP * 2.2 + vInst.y * 17.0;
285	  float cp = cells(pc);
286	  float kp = 1.0 - smoothstep(0.25, 0.5, fwidth(pc.x) * 2.0);
287	  col = mix(col, lav * 0.95, (1.0 - smoothstep(0.1, 0.2, cp)) * step(0.7, hash12(floor(pc) + vInst.y * 31.0)) * kp * 0.55 * lit);
288	  // soap-film rim: lavender with a hint of pink, darkest right at the silhouette (crevices in a pile)
289	  float fres = pow(1.0 - z, 1.8);
290	  col = mix(col, vec3(0.74, 0.62, 0.98), fres * 0.55);
291	  vec3 Lv = (viewMatrix * vec4(L, 0.0)).xyz;
292	  float spec = pow(max(dot(reflect(vec3(0.0, 0.0, -1.0), Nv), Lv), 0.0), 24.0);
293	  col += vec3(1.0) * spec * 0.32;
294	  col *= mix(0.7, 1.0, vInst.x);
295	  gl_FragColor = vec4(col, 1.0);
296	  ${FRAG_TAIL}
297	}
298	`;
299	
300	function makeBankBubbleMaterial() {
301	  const uniforms = withFog({
302	    uTime: { value: 0 },
303	    uLightDir: { value: new THREE.Vector3(0.3, 1.0, 0.45).normalize() },
304	  });
305	  const mat = new THREE.ShaderMaterial({ uniforms, vertexShader: BANK_BUB_VERT, fragmentShader: BANK_BUB_FRAG, fog: true });
306	  return { mat, uniforms };
307	}
