461	export function createFoam(
462	  course: Course,
463	  opts: { s0: number; s1: number; quality: 'high' | 'low'; height?: (s: number, lat: number, t: number) => number },
464	): FoamSystem {
465	  const { s0, s1, quality } = opts;
466	  const heightAt = opts.height ?? (() => 0);
467	  const rand = rng(1337);
468	  const density = quality === 'high' ? 1 : 0.5;
469	  // LOD: 80-tri puffs in the chunks around Benny, 20-tri puffs further out (low tier: 20-tri only)
470	  const geoHi = puffGeometry(quality === 'high' ? 1 : 0);
471	  const geoLo = quality === 'high' ? puffGeometry(0) : geoHi;
472	  const puff = makePuffMaterial(quality);
473	  const mat = puff.mat;
474	  const group = new THREE.Group();
475	  group.name = 'foam_banks';
476	  const st03 = course.stage('03'), st04 = course.stage('04');
477	  const chunkLen = 24;
478	  const chunks: { mesh: THREE.InstancedMesh; sa: number; sb: number }[] = [];
479	  let total = 0;
480	  const tmpM = new THREE.Matrix4();
481	  const tmpQ = new THREE.Quaternion();
482	  const tmpS = new THREE.Vector3();
483	  const tmpE = new THREE.Euler();
484	  const tmpC = new THREE.Color();
485	
486	  const build = (list: Puff[], parent: THREE.Object3D, sa: number, sb: number) => {
487	    if (!list.length) return;
488	    const mesh = new THREE.InstancedMesh(geoHi, mat, list.length);
489	    list.forEach((pf, i) => {
490	      tmpQ.setFromEuler(tmpE.set(rand() * 6, rand() * 6, rand() * 6));
491	      tmpS.set(pf.r, pf.r * (0.78 + rand() * 0.22), pf.r);
492	      tmpM.compose(pf.p, tmpQ, tmpS);
493	      mesh.setMatrixAt(i, tmpM);
494	      mesh.setColorAt(i, tmpC.setRGB(pf.ao, rand(), pf.tint));
495	    });
496	    mesh.instanceMatrix.needsUpdate = true;
497	    if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
498	    mesh.computeBoundingSphere();
499	    parent.add(mesh);
500	    chunks.push({ mesh, sa, sb });
501	    total += list.length;
502	  };
503	
504	  // ---- continuous lather bank (berm) along both edges ----
505	  const skip: [number, number] = [st03.s0 + 4, st04.s0 - 6];
506	  const berm = createBerm(course, s0, s1, skip, quality);
507	  group.add(berm.mesh);
508	
509	  // ---- cloud banks of puffs hugging both stream edges (ref 05: 10–40 px white-lavender clumps) ----
510	  const inSkip = (s: number) => s > skip[0] && s < skip[1];
511	  // wave 5: in 05 the stream-edge rim toward the VP is a LOW rim of piled bubbles (ref ≈40–60 px), not
512	  // tall heaps: crest puffs × 0.85, heaps × 0.6 and never stacked. Only sizes change, so the shared
513	  // rand() sequence (and every other stage's foam) stays identical.
514	  const st05b = course.stage('05');
515	  const bermK = bermScale05(course);
516	  const low05 = (s: number) => s > st05b.s0 - 4 && s < st05b.s1 + 2;
517	  const addPuff = (list: Puff[], s: number, e: number, side: number, r: number, lift: number, ao: number) => {
518	    const ss = Math.min(s1, Math.max(s0, s));
519	    if (inSkip(ss)) return;
520	    const f = course.sample(ss);
521	    const hw = course.widthAt(ss) / 2;
522	    const k05 = bermK(ss);
523	    const h = squashBerm(bermSurface(ss, e, side, hw), k05) + lift;
524	    const eS = e > 0 ? e * (0.1 + 0.9 * k05) : e;
525	    const p = f.pos.clone().addScaledVector(f.right, side * (hw + eS)).addScaledVector(f.up, h);
526	    list.push({ p, r, ao, tint: rand() * 2 - 1 });
527	  };
528	  const step = quality === 'high' ? 0.36 : 0.62;
529	  for (let sa = s0; sa < s1; sa += chunkLen) {
530	    const sb = Math.min(s1, sa + chunkLen);
531	    const list: Puff[] = [];
532	    // skip most of 03 (the whirlpool has its own foam), keep the chute→rim hand-over
533	    for (let s = sa; s < sb; s += step) {
534	      if (inSkip(s)) continue;
535	      for (const side of [-1, 1]) {
536	        // crest puffs: the body of the bank
537	        const nC = quality === 'high' && rand() < 0.55 ? 2 : 1;
538	        for (let k = 0; k < nC; k++) {
539	          const r = (0.11 + rand() * 0.13) * (low05(s) ? 0.85 : 1);
540	          addPuff(list, s + (rand() - 0.5) * step, -0.32 + rand() * 0.82, side, r, r * (0.05 + rand() * 0.3), 0.8 + 0.2 * rand());
541	        }
542	        // small puffs right at the water line (the lacy edge of the bank)
543	        if (rand() < 0.65) {
544	          const r = 0.06 + rand() * 0.06;
545	          addPuff(list, s + (rand() - 0.5) * step, -0.58 + rand() * 0.28, side, r, r * 0.15, 0.9);
546	        }
547	      }
548	      // heaps: clusters of big puffs stacked on the crest → lumpy cloud-bank silhouette
549	      if (rand() < (quality === 'high' ? 0.16 : 0.1)) {
550	        const side = rand() < 0.5 ? -1 : 1;
551	        const n = 5 + ((rand() * 6) | 0);
552	        const ec = -0.1 + rand() * 0.55;
553	        const lo = low05(s);
554	        for (let k = 0; k < n; k++) {
555	          const r = (0.15 + rand() * 0.18) * (lo ? 0.6 : 1);
556	          const stack = k > 2 && rand() < 0.4 && !lo ? r * 0.65 : 0;
557	          const lift = r * (0.1 + rand() * 0.45) + stack;
558	          addPuff(list, s + (rand() - 0.5) * 1.8, ec + (rand() - 0.5) * 0.55, side, r, lift, 0.72 + 0.28 * Math.min(1, lift / (r * 0.9)));
559	        }
560	      }
561	    }
562	    build(list, group, sa - 2, sb + 2);
563	  }
564	
565	  // ---- whirlpool: rim ring + spiral band foam (rotates with the swirl) ----
566	  const whirlGroup = new THREE.Group();
567	  whirlGroup.name = 'foam_whirlpool';
568	  const b = WORLD.basin;
569	  whirlGroup.position.set(b.center.x, 0, b.center.z);
570	  const wl: Puff[] = [];
571	  // rim: cloud clusters of soap foam with a thin continuous fringe between them
572	  const nClusters = Math.round(26 * density);
573	  for (let k = 0; k < nClusters; k++) {
574	    const th0 = rand() * Math.PI * 2;
575	    const n = 10 + ((rand() * 16) | 0);
576	    for (let i = 0; i < n; i++) {
577	      const th = th0 + (rand() - 0.5) * 0.35;
578	      const r = b.rimRadius - 0.7 + (rand() - 0.4) * 1.3;
579	      const sz = 0.18 + rand() * 0.42;
580	      wl.push({ p: new THREE.Vector3(r * Math.sin(th), funnelY(r) + FUNNEL_LIFT + sz * 0.35 + rand() * 0.55, r * Math.cos(th)), r: sz, ao: 0.75 + 0.25 * rand(), tint: rand() * 2 - 1 });
